"""Specification for the hard project. Do not edit this file."""

import dataclasses

import joblib
import numpy as np
import pandas as pd
import pytest
from sklearn.metrics import f1_score, recall_score, roc_auc_score

from fraud_pipeline import (
    FEATURES,
    SCHEMA_VERSION,
    TARGET,
    SchemaError,
    choose_threshold,
    load_bundle,
    make_transactions,
    predict,
    save_bundle,
    train,
    validate_input,
)


@pytest.fixture(scope="module")
def frames():
    df = make_transactions()
    return df.iloc[:6000].reset_index(drop=True), df.iloc[6000:].copy()


@pytest.fixture(scope="module")
def bundle(frames):
    return train(frames[0])


@pytest.fixture
def holdout(frames):
    return frames[1].copy()


def one_row(**overrides):
    row = {
        "amount": 45.0,
        "account_age_days": 365.0,
        "tx_count_24h": 2.0,
        "distance_from_home_km": 8.0,
        "merchant_category": "grocery",
        "channel": "card_present",
    }
    row.update(overrides)
    return pd.DataFrame([row])


# =====================================================================
# validate_input
# =====================================================================

def test_validate_rejects_missing_columns_and_names_them(holdout):
    with pytest.raises(SchemaError, match="amount"):
        validate_input(holdout.drop(columns=["amount"]))


def test_validate_rejects_empty_frame(holdout):
    with pytest.raises(SchemaError):
        validate_input(holdout.iloc[0:0])


def test_validate_rejects_non_dataframe():
    with pytest.raises(SchemaError):
        validate_input([[1, 2, 3]])


def test_validate_returns_only_contract_columns_in_contract_order(holdout):
    messy = holdout.copy()
    messy["transaction_id"] = range(len(messy))
    messy = messy[list(reversed(messy.columns))]
    out = validate_input(messy)
    assert list(out.columns) == FEATURES


def test_validate_coerces_bad_numbers_to_missing():
    df = one_row(account_age_days="abc", amount="52.5", tx_count_24h=np.inf)
    out = validate_input(df)
    assert np.isnan(out.loc[0, "account_age_days"])
    assert out.loc[0, "amount"] == 52.5
    assert np.isnan(out.loc[0, "tx_count_24h"])


def test_validate_normalises_text_categories():
    out = validate_input(one_row(merchant_category="  GroCERY ", channel=""))
    assert out.loc[0, "merchant_category"] == "grocery"
    assert pd.isna(out.loc[0, "channel"])


def test_validate_keeps_the_index(holdout):
    out = validate_input(holdout)
    assert out.index.equals(holdout.index)


def test_validate_does_not_modify_input(holdout):
    messy = holdout.copy()
    messy.loc[messy.index[0], "merchant_category"] = "  GROCERY "
    before = messy.copy(deep=True)
    _ = validate_input(messy)
    pd.testing.assert_frame_equal(messy, before)


# =====================================================================
# choose_threshold
# =====================================================================

def test_threshold_separates_perfectly_separable_scores():
    y = np.array([0, 0, 0, 0, 1, 1])
    s = np.array([0.1, 0.2, 0.3, 0.6, 0.7, 0.9])
    t = choose_threshold(y, s)
    assert ((s >= t).astype(int) == y).all()


def test_threshold_is_not_hardcoded_to_half():
    rng = np.random.default_rng(0)
    y = np.array([0] * 90 + [1] * 10)
    s = np.concatenate([rng.uniform(0.0, 0.2, 90), rng.uniform(0.25, 0.45, 10)])
    t = choose_threshold(y, s)
    assert f1_score(y, (s >= 0.5).astype(int), zero_division=0) == 0.0
    assert f1_score(y, (s >= t).astype(int)) >= 0.95


def test_threshold_is_a_plain_float_in_unit_interval():
    t = choose_threshold([0, 1, 0, 1], [0.2, 0.8, 0.4, 0.6])
    assert isinstance(t, float)
    assert 0.0 <= t <= 1.0


# =====================================================================
# train
# =====================================================================

def test_train_requires_target_column(frames):
    with pytest.raises(SchemaError, match=TARGET):
        train(frames[0].drop(columns=[TARGET]))


def test_train_requires_both_classes(frames):
    one_class = frames[0].copy()
    one_class[TARGET] = 0
    with pytest.raises(SchemaError):
        train(one_class)


def test_train_rejects_non_binary_target(frames):
    bad = frames[0].copy()
    bad.loc[bad.index[:5], TARGET] = 2
    with pytest.raises(SchemaError):
        train(bad)


def test_train_is_reproducible(frames, bundle, holdout):
    again = train(frames[0])
    assert again.threshold == bundle.threshold
    np.testing.assert_allclose(
        predict(again, holdout)["probability"].values,
        predict(bundle, holdout)["probability"].values,
    )


def test_train_handles_missing_categoricals_in_training_data(frames):
    # The generator puts ~5% missing values in 'merchant_category'. Training must survive that.
    assert frames[0]["merchant_category"].isna().any()
    assert train(frames[0]) is not None


def test_model_quality_on_unseen_data(bundle, holdout):
    out = predict(bundle, holdout)
    y = holdout[TARGET]
    assert roc_auc_score(y, out["probability"]) >= 0.8
    assert recall_score(y, out["label"]) >= 0.3
    assert f1_score(y, out["label"]) >= 0.3


# =====================================================================
# predict
# =====================================================================

def test_predict_output_shape_columns_and_index(bundle, holdout):
    shuffled = holdout.sample(frac=1.0, random_state=1)
    out = predict(bundle, shuffled)
    assert list(out.columns) == ["probability", "label"]
    assert out.index.equals(shuffled.index)
    assert out["probability"].between(0, 1).all()
    assert set(out["label"].unique()) <= {0, 1}


def test_predict_uses_the_bundle_threshold(bundle, holdout):
    always_positive = dataclasses.replace(bundle, threshold=0.0)
    always_negative = dataclasses.replace(bundle, threshold=1.01)
    assert (predict(always_positive, holdout)["label"] == 1).all()
    assert (predict(always_negative, holdout)["label"] == 0).all()


def test_predict_survives_unseen_categories(bundle):
    out = predict(bundle, one_row(merchant_category="space_station", channel="telepathy"))
    assert np.isfinite(out.loc[0, "probability"])


def test_predict_survives_all_features_missing(bundle):
    row = one_row()
    row.loc[0, :] = np.nan
    out = predict(bundle, row)
    assert np.isfinite(out.loc[0, "probability"])


def test_predict_ignores_extra_columns_and_column_order(bundle, holdout):
    clean = predict(bundle, holdout[FEATURES])
    messy = holdout.copy()
    messy["transaction_id"] = range(len(messy))
    messy = messy[list(reversed(messy.columns))]
    np.testing.assert_allclose(
        predict(bundle, messy)["probability"].values, clean["probability"].values
    )


def test_predict_does_not_need_the_target_column(bundle, holdout):
    out = predict(bundle, holdout.drop(columns=[TARGET]))
    assert len(out) == len(holdout)


def test_predict_works_for_a_single_row(bundle):
    out = predict(bundle, one_row())
    assert out.shape == (1, 2)


def test_predict_treats_text_variants_as_the_same_category(bundle):
    a = predict(bundle, one_row(merchant_category="grocery", channel="card_present"))
    b = predict(bundle, one_row(merchant_category="  GROCERY ", channel="Card_Present"))
    assert a.loc[0, "probability"] == pytest.approx(b.loc[0, "probability"])


def test_predict_accepts_numbers_stored_as_text(bundle):
    a = predict(bundle, one_row())
    b = predict(bundle, one_row(account_age_days="365", amount="45.0"))
    assert a.loc[0, "probability"] == pytest.approx(b.loc[0, "probability"])


def test_predict_raises_schema_error_for_missing_column(bundle, holdout):
    with pytest.raises(SchemaError, match="channel"):
        predict(bundle, holdout.drop(columns=["channel"]))


def test_predict_does_not_modify_input(bundle, holdout):
    before = holdout.copy(deep=True)
    _ = predict(bundle, holdout)
    pd.testing.assert_frame_equal(holdout, before)


# =====================================================================
# save_bundle / load_bundle
# =====================================================================

def test_save_and_load_round_trip(bundle, holdout, tmp_path):
    custom = dataclasses.replace(bundle, threshold=0.37)
    path = tmp_path / "bundle.joblib"
    save_bundle(custom, path)
    loaded = load_bundle(path)

    assert loaded.threshold == pytest.approx(0.37)
    assert loaded.schema_version == SCHEMA_VERSION
    pd.testing.assert_frame_equal(predict(loaded, holdout), predict(custom, holdout))


def test_load_rejects_wrong_schema_version(bundle, tmp_path):
    path = tmp_path / "old.joblib"
    joblib.dump(
        {
            "model": bundle.model,
            "threshold": 0.5,
            "schema_version": SCHEMA_VERSION + 998,
            "features": FEATURES,
        },
        path,
    )
    with pytest.raises(SchemaError, match="version"):
        load_bundle(path)


def test_load_rejects_a_bare_model_file(bundle, tmp_path):
    path = tmp_path / "bare.joblib"
    joblib.dump(bundle.model, path)
    with pytest.raises(SchemaError):
        load_bundle(path)


def test_load_raises_for_missing_file(tmp_path):
    with pytest.raises(FileNotFoundError):
        load_bundle(tmp_path / "does_not_exist.joblib")
